def transform(grid):
    from collections import Counter

    rows = len(grid)
    cols = len(grid[0])

    # Find horizontal divider rows (where a single value dominates)
    h_divs = []
    for r in range(rows):
        row_vals = Counter(grid[r])
        if row_vals and row_vals.most_common(1)[0][1] > cols * 0.3:
            h_divs.append(r)

    # Find vertical divider columns  
    v_divs = []
    for c in range(cols):
        col_vals = Counter(grid[r][c] for r in range(rows))
        if col_vals and col_vals.most_common(1)[0][1] > rows * 0.3:
            v_divs.append(c)

    # Ensure we get 4 horizontal and 5 vertical regions
    while len(h_divs) < 4:
        h_divs.append(None)
    while len(v_divs) < 5:
        v_divs.append(None)

    # Trim to exactly what we need
    h_divs = h_divs[:4]
    v_divs = v_divs[:5]

    # For each region, count marker values
    result = []
    for h in range(4):
        row_out = []
        for v in range(5):
            # If divider is None, use overall region boundaries
            if h_divs[h] is None:
                h_min = h * rows // 4
                h_max = (h + 1) * rows // 4
            else:
                h_min = h_divs[h]
                h_max = h_divs[h+1] if h+1 < len(h_divs) else rows

            if v_divs[v] is None:
                v_min = v * cols // 5
                v_max = (v + 1) * cols // 5
            else:
                v_min = v_divs[v]
                v_max = v_divs[v+1] if v+1 < len(v_divs) else cols

            # Get the dominant non-divider value or count markers
            cells = []
            for r in range(h_min, min(h_max, rows)):
                for c in range(v_min, min(v_max, cols)):
                    cells.append(grid[r][c])

            if cells:
                cnt = Counter(cells).most_common(6)
                # Use the most common value from top regions, or count something
                for i, (val, count) in enumerate(cnt):
                    if val not in [3, 9] and count > 0:
                        row_out.append(val)
                        break
                else:
                    row_out.append(cnt[0][0] if cnt else 0)
            else:
                row_out.append(0)

        result.append(row_out)

    return result
